{
  "status": "plan",
  "steps": [
    {
      "op": "derive",
      "input": "employees",
      "as": "employees_with_band",
      "column": "band",
      "expr": "'senior' if salary >= 140000 else ('mid' if salary >= 100000 else 'junior')"
    }
  ]
}

{
  "status": "plan",
  "steps": [
    {
      "op": "derive",
      "input": "students",
      "as": "students_with_total",
      "column": "total",
      "expr": "null if is_null(math) or is_null(science) or is_null(english) else math + science + english"
    }
  ]
}

{
  "status": "plan",
  "steps": [
    {
      "op": "filter",
      "input": "students",
      "as": "step1",
      "where": "not is_null(math) and not is_null(science) and not is_null(english)"
    },
    {
      "op": "derive",
      "input": "step1",
      "as": "step2",
      "column": "total",
      "expr": "math + science + english"
    },
    {
      "op": "select",
      "input": "step2",
      "as": "step3",
      "columns": ["name", "total"]
    },
    {
      "op": "sort",
      "input": "step3",
      "as": "output",
      "by": [
        {
          "column": "total",
          "order": "desc"
        }
      ]
    }
  ]
}

