{
  "status": "plan",
  "steps": [
    {
      "op": "derive",
      "input": "requests",
      "as": "with_flag",
      "column": "success_flag",
      "expr": "1 if (status >= 200 and status <= 299) else 0"
    },
    {
      "op": "aggregate",
      "input": "with_flag",
      "as": "agg",
      "group_by": ["endpoint"],
      "metrics": [
        {
          "as": "total",
          "fn": "count"
        },
        {
          "as": "success",
          "fn": "sum",
          "column": "success_flag"
        }
      ]
    },
    {
      "op": "derive",
      "input": "agg",
      "as": "with_pct",
      "column": "success_pct",
      "expr": "round(100 * success / total, digits=1)"
    },
    {
      "op": "select",
      "input": "with_pct",
      "as": "output",
      "columns": ["endpoint", "success_pct"]
    }
  ]
}

